INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('market exit', '', '', '[{"en":"The company planned an orderly market exit from underperforming regions.","zh-TW":"公司計劃從表現不佳的地區有序退出市場。"},{"en":"Market exit can release capital for more profitable ventures.","zh-TW":"退出市場可以為更有利可圖的企業釋放資金。"}]', 'phrasal verb'),
('competitive intelligence', '', '', '[{"en":"Competitive intelligence helped the firm anticipate a rival''s product launch.","zh-TW":"競爭情報幫助公司預測了競爭對手的產品發佈。"},{"en":"Regular competitive intelligence reviews keep the team informed.","zh-TW":"定期的競爭情報審查使團隊保持知情。"}]', 'phrasal verb'),
('barrier to entry', '', '', '[{"en":"Patents create a high barrier to entry in pharmaceutical markets.","zh-TW":"專利在藥品市場創造了高進入壁壘。"},{"en":"Strong brand loyalty is a significant barrier to entry for new competitors.","zh-TW":"強大的品牌忠誠度對新競爭對手是重大的進入壁壘。"}]', 'phrasal verb'),
('strategic fit', '', '', '[{"en":"The acquisition scored highly on strategic fit metrics.","zh-TW":"收購在戰略契合度指標上得分很高。"},{"en":"A lack of strategic fit was cited as the reason for abandoning the merger.","zh-TW":"缺乏戰略契合度被引用為放棄合併的原因。"}]', 'phrasal verb'),
('profit sharing', '', '', '[{"en":"The profit sharing plan motivated employees to improve company performance.","zh-TW":"利潤分享計劃激勵員工改善公司績效。"},{"en":"All staff received a profit sharing bonus after the record year.","zh-TW":"創紀錄的一年後，所有員工都獲得了利潤分享獎金。"}]', 'phrasal verb'),
('operating profit', '', '', '[{"en":"Operating profit rose 12% despite flat revenue growth.","zh-TW":"儘管收入增長持平，營業利潤增長了12%。"},{"en":"The operating profit margin widened as costs were cut.","zh-TW":"隨著成本削減，營業利潤率擴大了。"}]', 'phrasal verb'),
('operating cash flow', '', '', '[{"en":"Operating cash flow exceeded net income due to strong collections.","zh-TW":"由於強勁的收款，營業現金流超過了淨利潤。"},{"en":"Analysts use operating cash flow to assess business quality.","zh-TW":"分析師使用營業現金流評估業務質量。"}]', 'phrasal verb'),
('current assets', '', '', '[{"en":"Cash and inventory are the main current assets on the balance sheet.","zh-TW":"現金和庫存是資產負債表上的主要流動資產。"},{"en":"High current assets indicate strong short-term liquidity.","zh-TW":"高流動資產表明強勁的短期流動性。"}]', 'phrasal verb'),
('current liabilities', '', '', '[{"en":"Accounts payable and short-term loans are current liabilities.","zh-TW":"應付帳款和短期貸款是流動負債。"},{"en":"High current liabilities relative to assets can signal liquidity risk.","zh-TW":"相對於資產的高流動負債可能表明流動性風險。"}]', 'phrasal verb'),
('long-term debt', '', '', '[{"en":"The company refinanced its long-term debt at lower interest rates.","zh-TW":"公司以較低的利率再融資了長期債務。"},{"en":"Managing long-term debt is crucial for financial stability.","zh-TW":"管理長期債務對財務穩定至關重要。"}]', 'phrasal verb'),
('shareholders equity', '', '', '[{"en":"Shareholders equity grew as retained earnings accumulated over the years.","zh-TW":"隨著保留盈餘多年累積，股東權益增長了。"},{"en":"A negative shareholders equity indicates a company owes more than it owns.","zh-TW":"負股東權益表明公司負債超過資產。"}]', 'phrasal verb'),
('book value', '', '', '[{"en":"The stock was trading below its book value, suggesting undervaluation.","zh-TW":"股票以低於帳面價值的價格交易，表明被低估。"},{"en":"Goodwill is often carried on the balance sheet above its book value.","zh-TW":"商譽通常在資產負債表上以高於帳面價值的價格記錄。"}]', 'phrasal verb'),
('intrinsic value', '', '', '[{"en":"The analyst calculated the intrinsic value using a DCF model.","zh-TW":"分析師使用DCF模型計算了內在價值。"},{"en":"Buffett invests when a stock trades well below its intrinsic value.","zh-TW":"巴菲特在股票以遠低於其內在價值的價格交易時投資。"}]', 'phrasal verb'),
('boarding pass', '', '', '[{"en":"Please have your boarding pass ready at the gate.","zh-TW":"請在登機口備好登機證。"},{"en":"You can download your boarding pass to your phone.","zh-TW":"您可以把登機證下載到手機。"}]', 'phrasal verb'),
('business class', '', '', '[{"en":"She was upgraded to business class on the long-haul flight.","zh-TW":"她在長途飛行中升級到商務艙。"},{"en":"Business class passengers enjoy wider seats.","zh-TW":"商務艙乘客享有更寬的座位。"}]', 'phrasal verb'),
('cabin crew', '', '', '[{"en":"The cabin crew demonstrated the safety procedures.","zh-TW":"空服員示範了安全程序。"},{"en":"Please follow the instructions from the cabin crew.","zh-TW":"請遵循空服員的指示。"}]', 'phrasal verb'),
('connecting flight', '', '', '[{"en":"We have two hours before our connecting flight.","zh-TW":"我們在轉機前有兩小時。"},{"en":"Her connecting flight was delayed due to weather.","zh-TW":"她的轉機航班因天氣延誤。"}]', 'phrasal verb'),
('direct flight', '', '', '[{"en":"There are no direct flights to Vancouver from here.","zh-TW":"從這裡到溫哥華沒有直飛航班。"},{"en":"A direct flight will save us several hours.","zh-TW":"直飛航班將節省我們幾個小時。"}]', 'phrasal verb'),
('jet lag', '', '', '[{"en":"She suffered from jet lag after the long flight.","zh-TW":"長途飛行後她出現了時差反應。"},{"en":"Drinking plenty of water can help reduce jet lag.","zh-TW":"多喝水有助於減輕時差反應。"}]', 'phrasal verb'),
('overhead bin', '', '', '[{"en":"Please store your carry-on in the overhead bin.","zh-TW":"請將手提行李放入頭頂置物箱。"},{"en":"The overhead bins are full on this flight.","zh-TW":"這架航班的頭頂置物箱已滿。"}]', 'phrasal verb'),
('security check', '', '', '[{"en":"Please remove your shoes at the security check.","zh-TW":"請在安全檢查時脫鞋。"},{"en":"Allow extra time for the security check at busy airports.","zh-TW":"在繁忙機場請預留安全檢查額外時間。"}]', 'phrasal verb'),
('baggage claim', '', '', '[{"en":"Proceed to baggage claim after clearing customs.","zh-TW":"通關後請前往行李提領處。"},{"en":"Her suitcase was the last one on the baggage claim belt.","zh-TW":"她的行李箱是行李輸送帶上最後一件。"}]', 'phrasal verb'),
('travel insurance', '', '', '[{"en":"It is wise to purchase travel insurance before your trip.","zh-TW":"出行前購買旅遊保險是明智之舉。"},{"en":"Travel insurance covered her medical expenses abroad.","zh-TW":"旅遊保險支付了她在國外的醫療費用。"}]', 'phrasal verb'),
('car rental', '', '', '[{"en":"We arranged a car rental at the destination airport.","zh-TW":"我們在目的地機場安排了租車。"},{"en":"The car rental fee includes insurance.","zh-TW":"租車費用包含保險。"}]', 'phrasal verb'),
('tour guide', '', '', '[{"en":"Our tour guide was very knowledgeable about local history.","zh-TW":"我們的導遊對當地歷史非常了解。"},{"en":"The tour guide led the group through the museum.","zh-TW":"導遊帶領團體參觀博物館。"}]', 'phrasal verb'),
('package tour', '', '', '[{"en":"They chose a package tour to save money on their vacation.","zh-TW":"他們選擇套裝行程以節省度假費用。"},{"en":"The package tour includes hotel, meals, and guided tours.","zh-TW":"套裝行程包含飯店、餐食和導覽。"}]', 'phrasal verb'),
('aisle seat', '', '', '[{"en":"I always request an aisle seat for long flights.","zh-TW":"我長途飛行都要求走道座位。"},{"en":"The aisle seat gives you more legroom.","zh-TW":"走道座位給您更多腿部空間。"}]', 'phrasal verb'),
('window seat', '', '', '[{"en":"She chose a window seat to enjoy the view.","zh-TW":"她選擇靠窗座位以欣賞風景。"},{"en":"A window seat is great for sleeping on long flights.","zh-TW":"靠窗座位適合在長途飛行中睡覺。"}]', 'phrasal verb'),
('ground transportation', '', '', '[{"en":"The hotel provides free ground transportation from the airport.","zh-TW":"飯店提供機場免費地面交通接送。"},{"en":"Ground transportation is available at exit B.","zh-TW":"B出口有地面交通工具。"}]', 'phrasal verb'),
('seat assignment', '', '', '[{"en":"You can select your seat assignment during check-in.","zh-TW":"您可以在辦理登機手續時選擇座位。"},{"en":"His seat assignment was changed at the last minute.","zh-TW":"他的座位在最後一刻被更換了。"}]', 'phrasal verb'),
('cancellation policy', '', '', '[{"en":"Please read the cancellation policy before booking.","zh-TW":"預訂前請閱讀取消政策。"},{"en":"The hotel has a 48-hour cancellation policy.","zh-TW":"飯店有48小時取消政策。"}]', 'phrasal verb'),
('continental breakfast', '', '', '[{"en":"A continental breakfast is served from 7 to 10 am.","zh-TW":"歐式早餐從早上7點供應至10點。"},{"en":"The rate includes a daily continental breakfast.","zh-TW":"房價包含每日歐式早餐。"}]', 'phrasal verb'),
('deluxe room', '', '', '[{"en":"We booked a deluxe room with a city view.","zh-TW":"我們預訂了可欣賞城市景觀的豪華客房。"},{"en":"The deluxe room includes a king-size bed and jacuzzi.","zh-TW":"豪華客房包含特大床和按摩浴缸。"}]', 'phrasal verb'),
('dry cleaning', '', '', '[{"en":"The hotel offers a same-day dry cleaning service.","zh-TW":"飯店提供當天乾洗服務。"},{"en":"Please leave your items at the front desk for dry cleaning.","zh-TW":"請將衣物留在前台進行乾洗。"}]', 'phrasal verb'),
('express checkout', '', '', '[{"en":"Express checkout is available via the hotel app.","zh-TW":"快速退房可通過飯店應用程式辦理。"},{"en":"Leave your key card and use express checkout to save time.","zh-TW":"留下鑰匙卡並使用快速退房節省時間。"}]', 'phrasal verb'),
('fitness center', '', '', '[{"en":"The fitness center is open 24 hours a day.","zh-TW":"健身中心全天24小時開放。"},{"en":"Guests can enjoy the fully equipped fitness center.","zh-TW":"住客可享用設備齊全的健身中心。"}]', 'phrasal verb'),
('front desk', '', '', '[{"en":"Please collect your room key at the front desk.","zh-TW":"請在前台領取您的房間鑰匙。"},{"en":"The front desk is staffed 24 hours a day.","zh-TW":"前台全天24小時有工作人員。"}]', 'phrasal verb'),
('full board', '', '', '[{"en":"The resort offers a full board package for families.","zh-TW":"度假村為家庭提供全膳食服務套餐。"},{"en":"Full board includes breakfast, lunch, and dinner.","zh-TW":"全膳食服務包含早餐、午餐和晚餐。"}]', 'phrasal verb'),
('junior suite', '', '', '[{"en":"The junior suite includes a separate sitting area.","zh-TW":"小型套房包含獨立的休息區域。"},{"en":"We chose a junior suite for a more comfortable stay.","zh-TW":"我們選擇了小型套房以享受更舒適的住宿。"}]', 'phrasal verb'),
('laundry service', '', '', '[{"en":"The hotel provides a same-day laundry service.","zh-TW":"飯店提供當天洗衣服務。"},{"en":"Please fill out the laundry form in your room.","zh-TW":"請填寫房間內的洗衣單。"}]', 'phrasal verb'),
('on-site restaurant', '', '', '[{"en":"The on-site restaurant serves international cuisine.","zh-TW":"飯店內附設餐廳供應國際料理。"},{"en":"Guests receive a 15% discount at the on-site restaurant.","zh-TW":"住客在飯店內附設餐廳享有八五折優惠。"}]', 'phrasal verb'),
('rack rate', '', '', '[{"en":"Always negotiate below the rack rate when booking directly.","zh-TW":"直接訂房時務必嘗試低於公告房價。"},{"en":"The rack rate for the weekend is higher than usual.","zh-TW":"週末的標準房價高於平時。"}]', 'phrasal verb'),
('room service', '', '', '[{"en":"We ordered room service after arriving late at night.","zh-TW":"我們深夜抵達後點了客房服務。"},{"en":"Room service is available 24 hours a day.","zh-TW":"客房服務全天24小時提供。"}]', 'phrasal verb'),
('safe deposit', '', '', '[{"en":"Please use the safe deposit box for your valuables.","zh-TW":"請使用保險箱存放您的貴重物品。"},{"en":"The safe deposit box is located inside the wardrobe.","zh-TW":"保險箱位於衣櫥內。"}]', 'phrasal verb'),
('valet parking', '', '', '[{"en":"The hotel offers complimentary valet parking.","zh-TW":"飯店提供免費代客泊車服務。"},{"en":"Hand your keys to the valet parking attendant.","zh-TW":"請將鑰匙交給代客泊車服務員。"}]', 'phrasal verb'),
('wake-up call', '', '', '[{"en":"Please request a wake-up call for 6 am.","zh-TW":"請要求早上6點的叫醒服務。"},{"en":"The front desk will arrange a wake-up call for you.","zh-TW":"前台將為您安排叫醒服務。"}]', 'phrasal verb'),
('wellness center', '', '', '[{"en":"The resort''s wellness center offers yoga and meditation.","zh-TW":"度假村的健康中心提供瑜伽和冥想課程。"},{"en":"Book a treatment at the wellness center in advance.","zh-TW":"請提前預訂健康中心的療程。"}]', 'phrasal verb'),
('a la carte', '', '', '[{"en":"We ordered a la carte rather than the set menu.","zh-TW":"我們選擇單點而非套餐。"},{"en":"The a la carte menu offers more variety.","zh-TW":"單點菜單提供更多選擇。"}]', 'phrasal verb'),
('daily special', '', '', '[{"en":"The daily special today is grilled salmon with vegetables.","zh-TW":"今日特餐是烤鮭魚配蔬菜。"},{"en":"Ask the server what the daily special is.","zh-TW":"請詢問服務員今日特餐是什麼。"}]', 'phrasal verb'),
('dietary restriction', '', '', '[{"en":"Please inform us of any dietary restrictions in advance.","zh-TW":"請提前告知我們任何飲食限制。"},{"en":"We can accommodate most dietary restrictions upon request.","zh-TW":"我們可以根據要求滿足大多數飲食限制。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('house special', '', '', '[{"en":"The house special is a grilled seafood platter.","zh-TW":"本店特色菜是烤海鮮拼盤。"},{"en":"I recommend trying the house special tonight.","zh-TW":"我建議今晚嘗試本店特色菜。"}]', 'phrasal verb'),
('outdoor seating', '', '', '[{"en":"The cafe has outdoor seating overlooking the harbor.","zh-TW":"咖啡廳設有可俯瞰港灣的戶外座位。"},{"en":"Outdoor seating is available weather permitting.","zh-TW":"天氣允許時提供戶外座位。"}]', 'phrasal verb'),
('prix fixe', '', '', '[{"en":"The restaurant offers a prix fixe dinner on Saturdays.","zh-TW":"餐廳週六提供固定價位晚餐套餐。"},{"en":"The prix fixe menu includes three courses.","zh-TW":"固定價位套餐包含三道菜。"}]', 'phrasal verb'),
('set menu', '', '', '[{"en":"The set menu at lunch is a great value.","zh-TW":"午餐套餐非常划算。"},{"en":"We chose the three-course set menu for dinner.","zh-TW":"我們選擇了三道菜的晚餐套餐。"}]', 'phrasal verb'),
('tasting menu', '', '', '[{"en":"The tasting menu features eight courses of seasonal dishes.","zh-TW":"試菜菜單包含八道時令菜餚。"},{"en":"We opted for the tasting menu to try more dishes.","zh-TW":"我們選擇了試菜菜單以品嚐更多菜餚。"}]', 'phrasal verb'),
('wine list', '', '', '[{"en":"The sommelier helped us choose from the wine list.","zh-TW":"侍酒師幫助我們從酒單中選擇。"},{"en":"Their wine list features bottles from around the world.","zh-TW":"他們的酒單有來自世界各地的酒款。"}]', 'phrasal verb'),
('draft beer', '', '', '[{"en":"They have ten local draft beers on tap.","zh-TW":"他們有十種本地生啤酒可供選擇。"},{"en":"Draft beer is usually cheaper than bottled beer.","zh-TW":"生啤酒通常比瓶裝啤酒便宜。"}]', 'phrasal verb'),
('fast food', '', '', '[{"en":"Many travelers rely on fast food during long trips.","zh-TW":"許多旅行者在長途旅行中依賴速食。"},{"en":"Fast food chains are found in every major airport.","zh-TW":"每個主要機場都有速食連鎖店。"}]', 'phrasal verb'),
('food allergy', '', '', '[{"en":"Please notify the staff if you have a food allergy.","zh-TW":"如果您有食物過敏，請通知工作人員。"},{"en":"The kitchen takes food allergies very seriously.","zh-TW":"廚房非常重視食物過敏問題。"}]', 'phrasal verb'),
('benefit period', '', '', '[{"en":"Your benefit period begins on the date of enrollment.","zh-TW":"您的保險給付期間從入保日期開始計算。"},{"en":"Hospitalization is covered during the benefit period.","zh-TW":"住院費用在保險給付期間內承保。"}]', 'phrasal verb'),
('blood pressure', '', '', '[{"en":"The nurse checked his blood pressure every hour.","zh-TW":"護士每小時檢查他的血壓。"},{"en":"High blood pressure increases the risk of heart disease.","zh-TW":"高血壓增加了心臟病的風險。"}]', 'phrasal verb'),
('blood test', '', '', '[{"en":"The doctor ordered a blood test to check cholesterol.","zh-TW":"醫生要求進行血液檢查以檢測膽固醇。"},{"en":"Your blood test results will be ready in two days.","zh-TW":"您的血液檢查結果兩天後即可查看。"}]', 'phrasal verb'),
('generic drug', '', '', '[{"en":"Ask your pharmacist for a generic drug to save money.","zh-TW":"請詢問藥師是否有學名藥可節省費用。"},{"en":"Generic drugs are required to meet the same standards as brand-name drugs.","zh-TW":"學名藥必須符合與品牌藥相同的標準。"}]', 'phrasal verb'),
('health maintenance', '', '', '[{"en":"Health maintenance includes regular exercise and a balanced diet.","zh-TW":"健康維護包括定期運動和均衡飲食。"},{"en":"She enrolled in a health maintenance organization plan.","zh-TW":"她加入了健康維護組織計劃。"}]', 'phrasal verb'),
('lab test', '', '', '[{"en":"The doctor ordered several lab tests to confirm the diagnosis.","zh-TW":"醫生要求進行幾項化驗以確認診斷。"},{"en":"Lab test results are usually available within 24 hours.","zh-TW":"化驗結果通常在24小時內可查看。"}]', 'phrasal verb'),
('medical record', '', '', '[{"en":"Your medical record contains your full health history.","zh-TW":"您的病歷包含您完整的健康史。"},{"en":"Please bring your medical records to the appointment.","zh-TW":"請攜帶您的病歷前往就診。"}]', 'phrasal verb'),
('primary care', '', '', '[{"en":"Your primary care doctor handles routine health issues.","zh-TW":"您的基層醫療醫師處理例行健康問題。"},{"en":"Primary care is the first point of contact with the health system.","zh-TW":"基層醫療是與醫療體系的第一個接觸點。"}]', 'phrasal verb'),
('urgent care', '', '', '[{"en":"Go to urgent care for minor injuries or illnesses.","zh-TW":"輕傷或小病請前往緊急醫療護理中心就診。"},{"en":"Urgent care is faster than the emergency room for minor issues.","zh-TW":"對於小問題，緊急醫療護理比急診室更快。"}]', 'phrasal verb'),
('waiting period', '', '', '[{"en":"There is a six-month waiting period for maternity benefits.","zh-TW":"生育福利有六個月的等待期間。"},{"en":"The waiting period begins from the date of enrollment.","zh-TW":"等待期間從入保日期開始計算。"}]', 'phrasal verb'),
('wellness program', '', '', '[{"en":"The company offers a wellness program including gym membership.","zh-TW":"公司提供包含健身房會員的健康促進計劃。"},{"en":"Participating in the wellness program reduces insurance premiums.","zh-TW":"參與健康促進計劃可降低保險費。"}]', 'phrasal verb'),
('vision care', '', '', '[{"en":"Annual eye exams are included in the vision care plan.","zh-TW":"年度眼科檢查包含在視力保健計劃中。"},{"en":"Vision care benefits cover glasses and contact lenses.","zh-TW":"視力保健福利涵蓋眼鏡和隱形眼鏡。"}]', 'phrasal verb'),
('pre-existing condition', '', '', '[{"en":"Some insurance plans exclude pre-existing conditions.","zh-TW":"一些保險計劃不承保既往症。"},{"en":"Under current law, insurers cannot deny coverage for pre-existing conditions.","zh-TW":"依現行法律，保險公司不得以既往症為由拒絕承保。"}]', 'phrasal verb'),
('effective date', '', '', '[{"en":"The contract''s effective date is the first of next month.","zh-TW":"合約的生效日期是下個月的第一天。"},{"en":"Benefits begin on the effective date of the policy.","zh-TW":"福利從保單生效日期開始生效。"}]', 'phrasal verb'),
('governing law', '', '', '[{"en":"The governing law for this contract is the law of New York.","zh-TW":"本合約的準據法為紐約州法律。"},{"en":"Both parties agreed on the governing law before signing.","zh-TW":"雙方在簽署前就準據法達成一致。"}]', 'phrasal verb'),
('liquidated damages', '', '', '[{"en":"The contract includes a liquidated damages clause for late delivery.","zh-TW":"合約包含延遲交貨的約定損害賠償金條款。"},{"en":"Liquidated damages were set at five thousand dollars per day.","zh-TW":"約定損害賠償金設定為每天五千元。"}]', 'phrasal verb'),
('carbon emission', '', '', '[{"en":"The government set a target to reduce carbon emissions by 50%.","zh-TW":"政府設定了將碳排放量減少50%的目標。"},{"en":"Transportation is a major source of carbon emissions.","zh-TW":"交通運輸是碳排放的主要來源。"}]', 'phrasal verb'),
('carbon footprint', '', '', '[{"en":"Flying frequently increases your carbon footprint significantly.","zh-TW":"頻繁搭機會大幅增加您的碳足跡。"},{"en":"Companies are looking for ways to reduce their carbon footprint.","zh-TW":"企業正在尋找減少碳足跡的方法。"}]', 'phrasal verb'),
('carbon neutral', '', '', '[{"en":"The company pledged to become carbon neutral by 2030.","zh-TW":"公司承諾到2030年實現碳中和。"},{"en":"Carbon neutral products offset their emissions through reforestation.","zh-TW":"碳中和產品透過植樹造林來抵消排放量。"}]', 'phrasal verb'),
('carbon offset', '', '', '[{"en":"Travelers can purchase carbon offsets for their flights.","zh-TW":"旅客可以為其航班購買碳補償。"},{"en":"The company invested in carbon offset projects in developing countries.","zh-TW":"公司在發展中國家投資了碳補償項目。"}]', 'phrasal verb'),
('circular economy', '', '', '[{"en":"A circular economy reduces waste by reusing materials.","zh-TW":"循環經濟透過再利用材料來減少浪費。"},{"en":"The company shifted to a circular economy approach.","zh-TW":"公司轉向了循環經濟方式。"}]', 'phrasal verb'),
('clean energy', '', '', '[{"en":"Governments worldwide are investing in clean energy solutions.","zh-TW":"全球各國政府正在投資清潔能源解決方案。"},{"en":"Clean energy can reduce dependence on fossil fuels.","zh-TW":"清潔能源可以減少對化石燃料的依賴。"}]', 'phrasal verb'),
('climate change', '', '', '[{"en":"Climate change is causing more frequent extreme weather events.","zh-TW":"氣候變遷正在導致更頻繁的極端天氣事件。"},{"en":"International cooperation is needed to combat climate change.","zh-TW":"需要國際合作來應對氣候變遷。"}]', 'phrasal verb'),
('energy efficiency', '', '', '[{"en":"New appliances are designed for greater energy efficiency.","zh-TW":"新家電的設計旨在提高能源效率。"},{"en":"Energy efficiency reduces both costs and environmental impact.","zh-TW":"能源效率降低了成本和環境影響。"}]', 'phrasal verb'),
('fossil fuel', '', '', '[{"en":"The world is trying to reduce its dependence on fossil fuels.","zh-TW":"世界各地都在努力減少對化石燃料的依賴。"},{"en":"Burning fossil fuels releases greenhouse gases into the atmosphere.","zh-TW":"燃燒化石燃料會向大氣層釋放溫室氣體。"}]', 'phrasal verb'),
('global warming', '', '', '[{"en":"Global warming is melting polar ice caps.","zh-TW":"全球暖化正在融化極地冰帽。"},{"en":"Reducing greenhouse gas emissions is key to limiting global warming.","zh-TW":"減少溫室氣體排放是限制全球暖化的關鍵。"}]', 'phrasal verb'),
('green building', '', '', '[{"en":"The new office complex is certified as a green building.","zh-TW":"新辦公大樓獲得了綠色建築認證。"},{"en":"Green buildings use less energy and water than conventional ones.","zh-TW":"綠色建築比傳統建築使用更少的能源和水。"}]', 'phrasal verb'),
('greenhouse gas', '', '', '[{"en":"CO2 is the most common greenhouse gas produced by humans.","zh-TW":"二氧化碳是人類產生的最常見溫室氣體。"},{"en":"Reducing greenhouse gas emissions requires global cooperation.","zh-TW":"減少溫室氣體排放需要全球合作。"}]', 'phrasal verb'),
('hazardous waste', '', '', '[{"en":"Hazardous waste must be disposed of properly.","zh-TW":"有害廢棄物必須妥善處置。"},{"en":"The factory was fined for improper hazardous waste disposal.","zh-TW":"工廠因不當處置有害廢棄物而被罰款。"}]', 'phrasal verb'),
('net zero', '', '', '[{"en":"Many countries have pledged to reach net zero by 2050.","zh-TW":"許多國家承諾到2050年實現淨零排放。"},{"en":"Net zero requires both reducing emissions and capturing carbon.","zh-TW":"淨零排放需要同時減少排放量和捕獲碳。"}]', 'phrasal verb'),
('renewable energy', '', '', '[{"en":"Solar and wind are popular forms of renewable energy.","zh-TW":"太陽能和風能是受歡迎的再生能源形式。"},{"en":"Renewable energy is becoming more affordable each year.","zh-TW":"再生能源每年變得越來越實惠。"}]', 'phrasal verb'),
('solar energy', '', '', '[{"en":"The building generates its own electricity using solar energy.","zh-TW":"大樓使用太陽能自行發電。"},{"en":"Solar energy has become increasingly cost-competitive.","zh-TW":"太陽能的成本競爭力越來越強。"}]', 'phrasal verb'),
('sustainable development', '', '', '[{"en":"The UN''s sustainable development goals guide global policy.","zh-TW":"聯合國的永續發展目標指導全球政策。"},{"en":"Sustainable development balances economic growth with environmental care.","zh-TW":"永續發展平衡了經濟增長與環境保護。"}]', 'phrasal verb'),
('water conservation', '', '', '[{"en":"Water conservation is critical in drought-prone regions.","zh-TW":"水資源保育在乾旱易發地區至關重要。"},{"en":"Simple steps like fixing leaks support water conservation.","zh-TW":"修復漏水等簡單措施有助於節水。"}]', 'phrasal verb'),
('wind energy', '', '', '[{"en":"Wind energy is one of the fastest-growing energy sources.","zh-TW":"風能是增長最快的能源之一。"},{"en":"The offshore wind energy farm supplies power to 100,000 homes.","zh-TW":"離岸風力發電場為10萬戶家庭供電。"}]', 'phrasal verb'),
('electric vehicle', '', '', '[{"en":"Electric vehicles produce no direct carbon emissions.","zh-TW":"電動車不直接產生碳排放。"},{"en":"The government offers subsidies for purchasing electric vehicles.","zh-TW":"政府為購買電動車提供補貼。"}]', 'phrasal verb'),
('plastic waste', '', '', '[{"en":"Ocean plastic waste harms marine life significantly.","zh-TW":"海洋塑膠廢棄物對海洋生物造成嚴重危害。"},{"en":"The company pledged to eliminate single-use plastic waste.","zh-TW":"公司承諾消除一次性塑膠廢棄物。"}]', 'phrasal verb'),
('zero waste', '', '', '[{"en":"The office adopted a zero waste policy last year.","zh-TW":"辦公室去年採用了零廢棄政策。"},{"en":"Zero waste requires rethinking how products are designed.","zh-TW":"零廢棄需要重新思考產品的設計方式。"}]', 'phrasal verb'),
('air quality', '', '', '[{"en":"Poor air quality can cause respiratory problems.","zh-TW":"空氣品質差可能導致呼吸系統問題。"},{"en":"The city has installed sensors to monitor air quality.","zh-TW":"市政府安裝了感測器來監測空氣品質。"}]', 'phrasal verb'),
('responsible tourism', '', '', '[{"en":"Responsible tourism benefits local communities and ecosystems.","zh-TW":"負責任旅遊有益於當地社區和生態系統。"},{"en":"Choose eco-certified hotels as part of responsible tourism.","zh-TW":"選擇具有環保認證的飯店作為負責任旅遊的一部分。"}]', 'phrasal verb'),
('food waste', '', '', '[{"en":"The restaurant reduced food waste by 30% with better planning.","zh-TW":"餐廳透過更好的規劃將食物浪費減少了30%。"},{"en":"Food waste in landfills produces methane, a potent greenhouse gas.","zh-TW":"掩埋場中的廚餘會產生強效溫室氣體甲烷。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('distance learning', '', '', '[{"en":"Distance learning allows students to study at their own pace.","zh-TW":"遠距學習允許學生按自己的步調學習。"},{"en":"She completed her degree through distance learning while working.","zh-TW":"她在工作的同時透過遠距學習完成了學位。"}]', 'phrasal verb'),
('vocational training', '', '', '[{"en":"Vocational training programs prepare students for specific careers.","zh-TW":"職業培訓計劃為學生準備特定職業。"},{"en":"The government funds vocational training to reduce unemployment.","zh-TW":"政府資助職業培訓以降低失業率。"}]', 'phrasal verb'),
('study abroad', '', '', '[{"en":"He spent one year in Germany as part of his study abroad program.","zh-TW":"他作為海外留學計劃的一部分在德國待了一年。"},{"en":"Study abroad experiences enhance cross-cultural understanding.","zh-TW":"海外留學經驗增強了跨文化理解。"}]', 'phrasal verb'),
('contract employee', '', '', '[{"en":"The company hired contract employees for the seasonal workload.","zh-TW":"公司為季節性工作量聘用了約聘員工。"},{"en":"Contract employees are not entitled to the same benefits as permanent staff.","zh-TW":"約聘員工無權享受與正式員工相同的福利。"}]', 'phrasal verb'),
('human resources', '', '', '[{"en":"Contact the human resources department for leave requests.","zh-TW":"如需請假，請聯繫人力資源部門。"},{"en":"The human resources team manages recruiting and training.","zh-TW":"人力資源團隊負責招募和培訓。"}]', 'phrasal verb'),
('severance pay', '', '', '[{"en":"She received two months of severance pay when laid off.","zh-TW":"她被裁員時收到了兩個月的遣散費。"},{"en":"The severance pay package included unused vacation days.","zh-TW":"遣散費方案包含未使用的假期天數。"}]', 'phrasal verb'),
('virtual meeting', '', '', '[{"en":"Virtual meetings have replaced many in-person gatherings.","zh-TW":"線上會議已取代了許多面對面聚會。"},{"en":"She joined the virtual meeting from her home office.","zh-TW":"她從家庭辦公室加入了線上會議。"}]', 'phrasal verb'),
('baggage allowance', '', '', '[{"en":"Passengers in economy class have a 23 kg baggage allowance.","zh-TW":"經濟艙乘客有23公斤的行李限額。"},{"en":"Check the baggage allowance before packing.","zh-TW":"打包前請查看行李限額。"}]', 'phrasal verb'),
('border control', '', '', '[{"en":"All travelers must pass through border control upon arrival.","zh-TW":"所有旅客抵達時必須通過邊境管制。"},{"en":"Border control officers check passports and visas.","zh-TW":"邊境管制人員檢查護照和簽證。"}]', 'phrasal verb'),
('charter flight', '', '', '[{"en":"The tour company arranged a charter flight for the group.","zh-TW":"旅行社為團體安排了包機。"},{"en":"Charter flights are often used for corporate travel.","zh-TW":"包機常用於企業商務旅行。"}]', 'phrasal verb'),
('complimentary upgrade', '', '', '[{"en":"She received a complimentary upgrade to business class.","zh-TW":"她獲得了免費升等至商務艙。"},{"en":"Frequent flyers are often given complimentary upgrades.","zh-TW":"常旅客通常獲得免費升等。"}]', 'phrasal verb'),
('customs declaration', '', '', '[{"en":"Please complete the customs declaration form honestly.","zh-TW":"請如實填寫海關申報單。"},{"en":"Undeclared goods may be confiscated at customs.","zh-TW":"未申報的物品可能在海關被沒收。"}]', 'phrasal verb'),
('departure lounge', '', '', '[{"en":"Passengers gathered in the departure lounge before boarding.","zh-TW":"乘客在登機前聚集在候機廳。"},{"en":"The departure lounge has shops and restaurants.","zh-TW":"候機廳有商店和餐廳。"}]', 'phrasal verb'),
('economy class', '', '', '[{"en":"Economy class tickets are the most affordable option.","zh-TW":"經濟艙機票是最實惠的選擇。"},{"en":"The seats in economy class were narrow but comfortable.","zh-TW":"經濟艙的座位雖然窄但很舒適。"}]', 'phrasal verb'),
('first class', '', '', '[{"en":"First class passengers receive premium meals and service.","zh-TW":"頭等艙乘客享有高級餐食和服務。"},{"en":"The first class cabin has fully flat beds.","zh-TW":"頭等艙客艙配有全平躺式座椅。"}]', 'phrasal verb'),
('flight attendant', '', '', '[{"en":"The flight attendant helped the passenger with her luggage.","zh-TW":"空服員幫助乘客處理行李。"},{"en":"Flight attendants are trained in emergency procedures.","zh-TW":"空服員接受緊急程序培訓。"}]', 'phrasal verb'),
('frequent flyer', '', '', '[{"en":"Frequent flyer miles can be redeemed for free flights.","zh-TW":"常旅客里程可以兌換免費機票。"},{"en":"She is a gold member of the airline''s frequent flyer program.","zh-TW":"她是航空公司常旅客計劃的金卡會員。"}]', 'phrasal verb'),
('ground crew', '', '', '[{"en":"The ground crew prepared the aircraft for departure.","zh-TW":"地勤人員為飛機出發做好了準備。"},{"en":"Ground crew worked efficiently to turn around the flight.","zh-TW":"地勤人員高效地完成了飛機的周轉。"}]', 'phrasal verb'),
('hand luggage', '', '', '[{"en":"Your hand luggage must fit under the seat or overhead bin.","zh-TW":"您的手提行李必須放在座位下方或頭頂置物箱中。"},{"en":"Each passenger is allowed one piece of hand luggage.","zh-TW":"每位乘客可攜帶一件手提行李。"}]', 'phrasal verb'),
('hotel reservation', '', '', '[{"en":"Please make your hotel reservation at least two weeks ahead.","zh-TW":"請至少提前兩週預訂飯店。"},{"en":"Her hotel reservation was lost due to a system error.","zh-TW":"她的飯店預訂因系統錯誤而丟失。"}]', 'phrasal verb'),
('immigration card', '', '', '[{"en":"Please fill out the immigration card before landing.","zh-TW":"請在降落前填寫入境卡。"},{"en":"The immigration card asks for your intended length of stay.","zh-TW":"入境卡詢問您預計停留時間。"}]', 'phrasal verb'),
('jet bridge', '', '', '[{"en":"Passengers boarded the plane via the jet bridge.","zh-TW":"乘客透過登機橋登上飛機。"},{"en":"Small regional airports may lack jet bridges.","zh-TW":"小型地區機場可能沒有登機橋。"}]', 'phrasal verb'),
('lost and found', '', '', '[{"en":"He reported his missing bag to the lost and found.","zh-TW":"他向失物招領處報告了他遺失的包。"},{"en":"Check the airport lost and found for misplaced items.","zh-TW":"請在機場失物招領處查詢遺失物品。"}]', 'phrasal verb'),
('loyalty points', '', '', '[{"en":"She earned enough loyalty points for a free night.","zh-TW":"她積累了足夠的忠誠度積分兌換免費一晚住宿。"},{"en":"Loyalty points expire if not used within two years.","zh-TW":"忠誠度積分若兩年內未使用則到期失效。"}]', 'phrasal verb'),
('luggage tag', '', '', '[{"en":"Always attach a luggage tag to your checked bags.","zh-TW":"務必在託運行李上附上行李標籤。"},{"en":"The luggage tag helped identify her bag at baggage claim.","zh-TW":"行李標籤幫助她在行李提領處識別她的行李。"}]', 'phrasal verb'),
('mobile check-in', '', '', '[{"en":"Mobile check-in saves time at the airport.","zh-TW":"手機報到可以節省在機場的時間。"},{"en":"Download the airline app to use mobile check-in.","zh-TW":"下載航空公司應用程式以使用手機報到。"}]', 'phrasal verb'),
('motion sickness', '', '', '[{"en":"She takes medication to prevent motion sickness on long trips.","zh-TW":"她在長途旅行時服藥預防暈車。"},{"en":"Motion sickness is common during turbulent flights.","zh-TW":"在亂流飛行中暈機是很常見的。"}]', 'phrasal verb'),
('one-way ticket', '', '', '[{"en":"She bought a one-way ticket to start a new life abroad.","zh-TW":"她買了一張單程票，開始在國外的新生活。"},{"en":"A one-way ticket is often more expensive than half a roundtrip.","zh-TW":"單程票通常比來回票的一半還貴。"}]', 'phrasal verb'),
('rail pass', '', '', '[{"en":"A Europe rail pass offers unlimited travel on most trains.","zh-TW":"歐洲鐵路通票可在大多數火車上無限次乘坐。"},{"en":"The rail pass is valid for 15 days from first use.","zh-TW":"鐵路通票從首次使用起有效15天。"}]', 'phrasal verb'),
('return ticket', '', '', '[{"en":"A return ticket is usually cheaper than two single tickets.","zh-TW":"來回票通常比兩張單程票便宜。"},{"en":"She bought a return ticket to visit her family.","zh-TW":"她買了一張來回票拜訪家人。"}]', 'phrasal verb'),
('taxi rank', '', '', '[{"en":"There is a taxi rank just outside the arrivals terminal.","zh-TW":"入境大廳外面就有計程車站。"},{"en":"The taxi rank was very busy after the conference ended.","zh-TW":"會議結束後計程車站非常繁忙。"}]', 'phrasal verb'),
('transit visa', '', '', '[{"en":"Some nationalities require a transit visa to change planes.","zh-TW":"某些國籍需要過境簽證才能轉機。"},{"en":"Check if a transit visa is needed for your layover country.","zh-TW":"查看您的過境國家是否需要過境簽證。"}]', 'phrasal verb'),
('travel adapter', '', '', '[{"en":"Always bring a travel adapter when traveling abroad.","zh-TW":"出國旅行時務必攜帶旅行轉接頭。"},{"en":"A universal travel adapter works in most countries.","zh-TW":"萬用旅行轉接頭適用於大多數國家。"}]', 'phrasal verb'),
('travel agent', '', '', '[{"en":"A travel agent helped them plan their honeymoon itinerary.","zh-TW":"旅行社業務員幫助他們規劃了蜜月行程。"},{"en":"Many people still prefer using a travel agent for complex trips.","zh-TW":"許多人仍偏好使用旅行社業務員安排複雜行程。"}]', 'phrasal verb'),
('travel document', '', '', '[{"en":"Keep all travel documents together in a safe place.","zh-TW":"將所有旅行證件放在安全的地方一起保管。"},{"en":"Losing travel documents abroad can cause serious problems.","zh-TW":"在國外遺失旅行證件可能造成嚴重問題。"}]', 'phrasal verb'),
('dietary supplement', '', '', '[{"en":"Vitamin D is a common dietary supplement.","zh-TW":"維生素D是常見的膳食補充品。"},{"en":"Always consult a doctor before taking dietary supplements.","zh-TW":"服用膳食補充品前務必諮詢醫生。"}]', 'phrasal verb'),
('dining experience', '', '', '[{"en":"The restaurant offers an unforgettable dining experience.","zh-TW":"這家餐廳提供難忘的用餐體驗。"},{"en":"A good dining experience goes beyond just the food.","zh-TW":"良好的用餐體驗不僅僅是食物。"}]', 'phrasal verb'),
('high tea', '', '', '[{"en":"They enjoyed high tea at a luxury hotel.","zh-TW":"他們在豪華飯店享用了英式下午茶。"},{"en":"High tea typically includes finger sandwiches and scones.","zh-TW":"英式下午茶通常包括小三明治和司康。"}]', 'phrasal verb'),
('maître d''', '', '', '[{"en":"The maître d'' escorted us to our reserved table.","zh-TW":"領班帶領我們到預訂的桌位。"},{"en":"The maître d'' ensured every guest was well taken care of.","zh-TW":"領班確保每位賓客都得到妥善照顧。"}]', 'phrasal verb'),
('open kitchen', '', '', '[{"en":"The restaurant features an open kitchen where guests can watch the chefs.","zh-TW":"餐廳設有開放式廚房，賓客可以觀看廚師烹飪。"},{"en":"An open kitchen adds transparency and excitement to dining.","zh-TW":"開放式廚房為用餐增添了透明度和刺激感。"}]', 'phrasal verb'),
('outdoor dining', '', '', '[{"en":"The restaurant''s outdoor dining area overlooks the river.","zh-TW":"餐廳的戶外用餐區可俯瞰河流。"},{"en":"Outdoor dining is popular in warm weather.","zh-TW":"在溫暖的天氣中，戶外用餐很受歡迎。"}]', 'phrasal verb'),
('signature dish', '', '', '[{"en":"The restaurant''s signature dish is the Peking duck.","zh-TW":"這家餐廳的招牌菜是北京烤鴨。"},{"en":"Every great chef has their own signature dish.","zh-TW":"每位出色的廚師都有自己的招牌菜。"}]', 'phrasal verb'),
('three-course meal', '', '', '[{"en":"The anniversary dinner included a romantic three-course meal.","zh-TW":"週年紀念晚餐包含了浪漫的三道菜大餐。"},{"en":"A three-course meal at this restaurant costs 60 dollars.","zh-TW":"這家餐廳的三道菜套餐售價60元。"}]', 'phrasal verb'),
('wine pairing', '', '', '[{"en":"The sommelier offered wine pairing suggestions with each course.","zh-TW":"侍酒師為每道菜提供了餐酒搭配建議。"},{"en":"Good wine pairing enhances both the food and the wine.","zh-TW":"良好的餐酒搭配同時提升了食物和葡萄酒的風味。"}]', 'phrasal verb'),
('budget proposal', '', '', '[{"en":"The department submitted its budget proposal for next year.","zh-TW":"部門提交了明年的預算提案。"},{"en":"The budget proposal was approved by the finance committee.","zh-TW":"預算提案獲得了財務委員會批准。"}]', 'phrasal verb'),
('business card', '', '', '[{"en":"He exchanged business cards with the potential client.","zh-TW":"他與潛在客戶交換了名片。"},{"en":"Always bring plenty of business cards to conferences.","zh-TW":"參加會議時務必帶足名片。"}]', 'phrasal verb'),
('minutes of meeting', '', '', '[{"en":"The secretary circulated the minutes of meeting to all attendees.","zh-TW":"秘書將會議記錄發送給所有與會者。"},{"en":"Please review and approve the minutes of last week''s meeting.","zh-TW":"請查看並批准上週的會議記錄。"}]', 'phrasal verb'),
('overhead projector', '', '', '[{"en":"The meeting room has a new overhead projector.","zh-TW":"會議室有一台新的投影機。"},{"en":"The trainer used an overhead projector to display the slides.","zh-TW":"培訓師使用投影機展示投影片。"}]', 'phrasal verb'),
('project manager', '', '', '[{"en":"The project manager ensured all deadlines were met.","zh-TW":"項目經理確保所有截止日期都能達成。"},{"en":"A skilled project manager keeps the team on track.","zh-TW":"有技能的項目經理使團隊保持正軌。"}]', 'phrasal verb'),
('customs clearance', '', '', '[{"en":"Proper documentation speeds up customs clearance.","zh-TW":"適當的文件加快了通關程序。"},{"en":"The goods were held up awaiting customs clearance.","zh-TW":"貨物因等待通關而被扣押。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('tracking number', '', '', '[{"en":"Use the tracking number to check your delivery status.","zh-TW":"使用追蹤號碼查看您的配送狀態。"},{"en":"You will receive a tracking number once the order is dispatched.","zh-TW":"訂單發出後您將收到追蹤號碼。"}]', 'phrasal verb'),
('down payment', '', '', '[{"en":"A 20% down payment is typically required for a mortgage.","zh-TW":"購買房屋通常需要20%的頭期款。"},{"en":"She saved for years to accumulate the down payment.","zh-TW":"她存了多年才積累到頭期款。"}]', 'phrasal verb'),
('property tax', '', '', '[{"en":"Property taxes in this area increased by five percent.","zh-TW":"該地區的房產稅增加了五個百分點。"},{"en":"Property tax revenue funds local schools and services.","zh-TW":"房產稅收入資助當地學校和服務。"}]', 'phrasal verb'),
('real estate agent', '', '', '[{"en":"A real estate agent helped them find their dream home.","zh-TW":"房地產經紀人幫助他們找到了夢想中的家。"},{"en":"Choose a real estate agent with knowledge of the local market.","zh-TW":"選擇熟悉當地市場的房地產經紀人。"}]', 'phrasal verb'),
('vacancy rate', '', '', '[{"en":"A high vacancy rate indicates weak demand in the market.","zh-TW":"高空置率表明市場需求疲軟。"},{"en":"The building''s vacancy rate dropped to 3% this year.","zh-TW":"今年大樓的空置率降至3%。"}]', 'phrasal verb'),
('warranty claim', '', '', '[{"en":"She filed a warranty claim for the defective laptop.","zh-TW":"她就有問題的筆記型電腦提出了保固索賠。"},{"en":"Warranty claims must be submitted within the warranty period.","zh-TW":"保固索賠必須在保固期內提交。"}]', 'phrasal verb'),
('blood type', '', '', '[{"en":"It is important to know your blood type in case of emergency.","zh-TW":"在緊急情況下知道自己的血型非常重要。"},{"en":"The doctor asked about her blood type before surgery.","zh-TW":"醫生在手術前詢問了她的血型。"}]', 'phrasal verb'),
('chronic disease', '', '', '[{"en":"Diabetes is one of the most common chronic diseases.","zh-TW":"糖尿病是最常見的慢性疾病之一。"},{"en":"Lifestyle changes can help manage many chronic diseases.","zh-TW":"生活方式的改變有助於控制許多慢性疾病。"}]', 'phrasal verb'),
('emergency contact', '', '', '[{"en":"Please provide an emergency contact on the registration form.","zh-TW":"請在登記表上提供緊急聯絡人。"},{"en":"The hospital called the patient''s emergency contact.","zh-TW":"醫院聯絡了患者的緊急聯絡人。"}]', 'phrasal verb'),
('medical history', '', '', '[{"en":"The doctor reviewed her medical history before the examination.","zh-TW":"醫生在檢查前查看了她的病史。"},{"en":"Always bring your medical history when seeing a new doctor.","zh-TW":"看新醫生時務必攜帶您的病史。"}]', 'phrasal verb'),
('physical therapy', '', '', '[{"en":"Physical therapy helped her regain strength after the surgery.","zh-TW":"物理治療幫助她在手術後恢復了力量。"},{"en":"The doctor recommended twice-weekly physical therapy.","zh-TW":"醫生建議每週兩次物理治療。"}]', 'phrasal verb'),
('prescription drug', '', '', '[{"en":"Prescription drugs are covered under the health plan.","zh-TW":"處方藥在健康計劃下獲得承保。"},{"en":"Some prescription drugs are only available at hospital pharmacies.","zh-TW":"某些處方藥只在醫院藥局供應。"}]', 'phrasal verb'),
('specialist referral', '', '', '[{"en":"She obtained a specialist referral to see a cardiologist.","zh-TW":"她獲得了轉診心臟科專科醫生的推介信。"},{"en":"Insurance may require a specialist referral before coverage applies.","zh-TW":"保險可能要求專科轉診後才提供承保。"}]', 'phrasal verb'),
('vital signs', '', '', '[{"en":"The nurse checked the patient''s vital signs every hour.","zh-TW":"護士每小時檢查病患的生命體徵。"},{"en":"Vital signs include temperature, pulse, and blood pressure.","zh-TW":"生命體徵包括體溫、脈搏和血壓。"}]', 'phrasal verb'),
('carbon trading', '', '', '[{"en":"Carbon trading encourages companies to reduce emissions.","zh-TW":"碳交易鼓勵企業減少排放量。"},{"en":"The carbon trading market has grown significantly in recent years.","zh-TW":"近年來碳交易市場大幅成長。"}]', 'phrasal verb'),
('endangered species', '', '', '[{"en":"Polar bears are classified as an endangered species.","zh-TW":"北極熊被列為瀕危物種。"},{"en":"Conservation programs help protect endangered species.","zh-TW":"保育計劃有助於保護瀕危物種。"}]', 'phrasal verb'),
('environmental impact', '', '', '[{"en":"Companies must assess the environmental impact of their operations.","zh-TW":"企業必須評估其運營的環境影響。"},{"en":"The construction project''s environmental impact was carefully reviewed.","zh-TW":"建設項目的環境影響受到了仔細審查。"}]', 'phrasal verb'),
('green technology', '', '', '[{"en":"Green technology is driving the clean energy revolution.","zh-TW":"綠色技術正在推動清潔能源革命。"},{"en":"The company invested in green technology to cut its emissions.","zh-TW":"公司投資了綠色技術以減少排放量。"}]', 'phrasal verb'),
('habitat loss', '', '', '[{"en":"Habitat loss is the leading cause of biodiversity decline.","zh-TW":"棲地喪失是生物多樣性下降的主要原因。"},{"en":"Urban development often leads to significant habitat loss.","zh-TW":"城市開發往往導致嚴重的棲地喪失。"}]', 'phrasal verb'),
('ocean pollution', '', '', '[{"en":"Ocean pollution threatens marine biodiversity.","zh-TW":"海洋污染威脅海洋生物多樣性。"},{"en":"Reducing plastic waste is key to addressing ocean pollution.","zh-TW":"減少塑膠廢棄物是解決海洋污染的關鍵。"}]', 'phrasal verb'),
('ozone layer', '', '', '[{"en":"Chemicals like CFCs have damaged the ozone layer.","zh-TW":"氟氯碳化物等化學物質破壞了臭氧層。"},{"en":"International agreements have helped slow ozone layer depletion.","zh-TW":"國際協議有助於減緩臭氧層耗損。"}]', 'phrasal verb'),
('sustainable sourcing', '', '', '[{"en":"The company adopted a sustainable sourcing policy for all suppliers.","zh-TW":"公司對所有供應商採用了永續採購政策。"},{"en":"Sustainable sourcing helps preserve natural resources.","zh-TW":"永續採購有助於保護自然資源。"}]', 'phrasal verb'),
('account holder', '', '', '[{"en":"The account holder must sign all withdrawal forms.","zh-TW":"帳戶持有人必須在所有提款單上簽名。"},{"en":"She is the primary account holder on the joint account.","zh-TW":"她是聯名帳戶的主要帳戶持有人。"}]', 'phrasal verb'),
('bank transfer', '', '', '[{"en":"She initiated a bank transfer to pay the vendor.","zh-TW":"她發起了一筆銀行轉帳來支付供應商款項。"},{"en":"International bank transfers may take two to five business days.","zh-TW":"國際銀行轉帳可能需要兩到五個工作日。"}]', 'phrasal verb'),
('credit card', '', '', '[{"en":"She paid for the hotel room using her credit card.","zh-TW":"她使用信用卡支付了飯店房費。"},{"en":"Check your credit card statement regularly for errors.","zh-TW":"定期查看您的信用卡帳單以確認是否有錯誤。"}]', 'phrasal verb'),
('currency exchange', '', '', '[{"en":"Look for the best currency exchange rate before traveling.","zh-TW":"出行前尋找最佳的貨幣兌換匯率。"},{"en":"Currency exchange services are available at most airports.","zh-TW":"大多數機場都有貨幣兌換服務。"}]', 'phrasal verb'),
('debit card', '', '', '[{"en":"He prefers to pay with a debit card to avoid debt.","zh-TW":"他偏好使用簽帳金融卡以避免負債。"},{"en":"Enter your PIN when paying by debit card.","zh-TW":"使用簽帳金融卡付款時請輸入您的密碼。"}]', 'phrasal verb'),
('exchange rate', '', '', '[{"en":"The exchange rate affected the cost of our overseas purchase.","zh-TW":"匯率影響了我們的海外採購成本。"},{"en":"Monitor exchange rate fluctuations before converting money.","zh-TW":"在換錢前監測匯率波動。"}]', 'phrasal verb'),
('online banking', '', '', '[{"en":"Online banking makes it easy to manage your finances anywhere.","zh-TW":"網路銀行使您可以在任何地方輕鬆管理財務。"},{"en":"Always log out after using online banking on a public computer.","zh-TW":"在公共電腦上使用網路銀行後請務必登出。"}]', 'phrasal verb'),
('savings account', '', '', '[{"en":"Opening a savings account is the first step to financial security.","zh-TW":"開設儲蓄帳戶是財務安全的第一步。"},{"en":"The savings account offered a competitive interest rate.","zh-TW":"該儲蓄帳戶提供了有競爭力的利率。"}]', 'phrasal verb'),
('wire transfer', '', '', '[{"en":"The company sent a wire transfer to pay the foreign supplier.","zh-TW":"公司發送了電匯支付給外國供應商。"},{"en":"Wire transfers usually arrive within one to two business days.","zh-TW":"電匯通常在一到兩個工作日內到達。"}]', 'phrasal verb'),
('academic year', '', '', '[{"en":"The academic year begins in September and ends in June.","zh-TW":"學年從9月開始，6月結束。"},{"en":"Registration opens two months before the academic year begins.","zh-TW":"入學申請在學年開始前兩個月開放。"}]', 'phrasal verb'),
('aptitude test', '', '', '[{"en":"The company uses aptitude tests to screen candidates.","zh-TW":"公司使用性向測驗篩選候選人。"},{"en":"Her aptitude test results showed strong analytical skills.","zh-TW":"她的性向測驗結果顯示出強大的分析能力。"}]', 'phrasal verb'),
('core curriculum', '', '', '[{"en":"Students must complete the core curriculum before choosing electives.","zh-TW":"學生必須完成核心課程後才能選擇選修課。"},{"en":"The core curriculum includes math, science, and language arts.","zh-TW":"核心課程包括數學、科學和語言藝術。"}]', 'phrasal verb'),
('credit hour', '', '', '[{"en":"The degree requires a total of 120 credit hours.","zh-TW":"該學位需要總共120個學分。"},{"en":"Students typically take 15 credit hours per semester.","zh-TW":"學生每學期通常修讀15個學分。"}]', 'phrasal verb'),
('doctoral degree', '', '', '[{"en":"Earning a doctoral degree requires years of research.","zh-TW":"獲得博士學位需要多年的研究。"},{"en":"She completed her doctoral degree in three years.","zh-TW":"她在三年內完成了博士學位。"}]', 'phrasal verb'),
('exchange student', '', '', '[{"en":"She participated as an exchange student in Germany.","zh-TW":"她以交換學生的身份在德國學習。"},{"en":"Exchange student programs promote cultural understanding.","zh-TW":"交換學生計劃促進了文化理解。"}]', 'phrasal verb'),
('online course', '', '', '[{"en":"She took an online course to improve her data skills.","zh-TW":"她參加了一門線上課程以提升數據技能。"},{"en":"Online courses offer flexibility for working adults.","zh-TW":"線上課程為在職成人提供了靈活性。"}]', 'phrasal verb'),
('research paper', '', '', '[{"en":"She published a research paper in an international journal.","zh-TW":"她在國際期刊上發表了一篇研究論文。"},{"en":"The research paper must follow the APA citation format.","zh-TW":"研究論文必須遵循APA引用格式。"}]', 'phrasal verb'),
('student loan', '', '', '[{"en":"Student loans must be repaid after graduation.","zh-TW":"學生貸款必須在畢業後償還。"},{"en":"Many students rely on student loans to fund their education.","zh-TW":"許多學生依靠學生貸款資助他們的教育。"}]', 'phrasal verb'),
('pass mark', '', '', '[{"en":"The pass mark for the exam is 60%.","zh-TW":"這門考試的及格分數是60%。"},{"en":"She exceeded the pass mark by 20 points.","zh-TW":"她超過及格分數20分。"}]', 'phrasal verb'),
('big data', '', '', '[{"en":"Big data analytics helps businesses make better decisions.","zh-TW":"大數據分析幫助企業做出更好的決策。"},{"en":"The company invested in big data infrastructure.","zh-TW":"公司投資了大數據基礎設施。"}]', 'phrasal verb'),
('IT support', '', '', '[{"en":"Contact IT support if you experience login issues.","zh-TW":"如果遇到登入問題，請聯繫資訊技術支援。"},{"en":"The IT support team responded to the outage within minutes.","zh-TW":"資訊技術支援團隊在幾分鐘內回應了系統中斷。"}]', 'phrasal verb'),
('software update', '', '', '[{"en":"Install the latest software update for improved security.","zh-TW":"安裝最新的軟體更新以提升安全性。"},{"en":"Software updates often include important security patches.","zh-TW":"軟體更新通常包括重要的安全修補程式。"}]', 'phrasal verb'),
('system administrator', '', '', '[{"en":"The system administrator set up the new employee accounts.","zh-TW":"系統管理員設置了新員工的帳號。"},{"en":"Report technical issues to the system administrator.","zh-TW":"向系統管理員報告技術問題。"}]', 'phrasal verb'),
('two-factor authentication', '', '', '[{"en":"Enable two-factor authentication for added account security.","zh-TW":"啟用雙重驗證以提高帳戶安全性。"},{"en":"Two-factor authentication greatly reduces the risk of unauthorized access.","zh-TW":"雙重驗證大大降低了未授權訪問的風險。"}]', 'phrasal verb'),
('user account', '', '', '[{"en":"Create a user account to access the platform.","zh-TW":"建立使用者帳號以訪問平台。"},{"en":"The system administrator manages all user accounts.","zh-TW":"系統管理員管理所有使用者帳號。"}]', 'phrasal verb'),
('web browser', '', '', '[{"en":"Clear your web browser''s cache to improve performance.","zh-TW":"清除您的網頁瀏覽器快取以提升效能。"},{"en":"The website is compatible with all major web browsers.","zh-TW":"該網站與所有主要網頁瀏覽器相容。"}]', 'phrasal verb'),
('competitor analysis', '', '', '[{"en":"Regular competitor analysis keeps the company informed.","zh-TW":"定期進行競爭對手分析使公司保持了解。"},{"en":"The marketing team prepared a competitor analysis report.","zh-TW":"行銷團隊準備了競爭對手分析報告。"}]', 'phrasal verb'),
('digital marketing', '', '', '[{"en":"Digital marketing has become the dominant form of advertising.","zh-TW":"數位行銷已成為主要的廣告形式。"},{"en":"The company''s digital marketing team manages social media accounts.","zh-TW":"公司的數位行銷團隊管理社交媒體帳號。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('marketing mix', '', '', '[{"en":"The classic marketing mix includes product, price, place, and promotion.","zh-TW":"傳統的行銷組合包括產品、價格、通路和促銷。"},{"en":"An effective marketing mix drives both sales and brand awareness.","zh-TW":"有效的行銷組合同時推動了銷售和品牌知名度。"}]', 'phrasal verb'),
('social media', '', '', '[{"en":"Social media marketing has become essential for brands.","zh-TW":"社交媒體行銷已成為品牌的必要手段。"},{"en":"The post went viral on social media overnight.","zh-TW":"這篇帖子在一夜之間在社交媒體上瘋傳。"}]', 'phrasal verb'),
('viral marketing', '', '', '[{"en":"The video became a viral marketing success overnight.","zh-TW":"這段影片在一夜之間成為病毒式行銷的成功案例。"},{"en":"Viral marketing can reach millions without a large budget.","zh-TW":"病毒式行銷無需大預算即可觸達數百萬人。"}]', 'phrasal verb'),
('business development', '', '', '[{"en":"The business development team identified new markets.","zh-TW":"業務發展團隊發現了新市場。"},{"en":"Business development requires creativity and persistence.","zh-TW":"業務發展需要創造力和堅持不懈。"}]', 'phrasal verb'),
('overhead costs', '', '', '[{"en":"The company cut overhead costs by switching to remote work.","zh-TW":"公司透過轉向遠端工作降低了間接費用。"},{"en":"Overhead costs include rent, utilities, and administrative salaries.","zh-TW":"間接費用包括租金、水電費和行政薪資。"}]', 'phrasal verb'),
('revenue stream', '', '', '[{"en":"The company developed multiple revenue streams to reduce risk.","zh-TW":"公司開發了多個收益來源以降低風險。"},{"en":"Subscription services became a significant revenue stream.","zh-TW":"訂閱服務成為了重要的收益來源。"}]', 'phrasal verb'),
('administrative assistant', '', '', '[{"en":"The administrative assistant scheduled all meetings.","zh-TW":"行政助理安排了所有會議。"},{"en":"A reliable administrative assistant is essential for a smooth operation.","zh-TW":"可靠的行政助理對於順暢運作至關重要。"}]', 'phrasal verb'),
('annual leave', '', '', '[{"en":"Employees receive 15 days of annual leave per year.","zh-TW":"員工每年獲得15天年假。"},{"en":"Please submit your annual leave request two weeks in advance.","zh-TW":"請提前兩週提交年假申請。"}]', 'phrasal verb'),
('business hours', '', '', '[{"en":"Our offices are open during regular business hours.","zh-TW":"我們的辦公室在正常辦公時間開放。"},{"en":"Please contact us during business hours for assistance.","zh-TW":"請在辦公時間內與我們聯繫以獲取協助。"}]', 'phrasal verb'),
('business trip', '', '', '[{"en":"He went on a business trip to Tokyo for three days.","zh-TW":"他出差去東京出差了三天。"},{"en":"All business trip expenses must be submitted with receipts.","zh-TW":"所有出差費用必須附有收據提交。"}]', 'phrasal verb'),
('copy machine', '', '', '[{"en":"The copy machine was out of paper during the meeting.","zh-TW":"會議期間影印機沒有紙了。"},{"en":"Please clear any paper jams in the copy machine.","zh-TW":"請清除影印機中的任何卡紙。"}]', 'phrasal verb'),
('expense report', '', '', '[{"en":"Please submit your expense report by the end of the month.","zh-TW":"請在月底前提交您的費用報告。"},{"en":"All receipts must be attached to the expense report.","zh-TW":"所有收據必須附在費用報告上。"}]', 'phrasal verb'),
('flexible hours', '', '', '[{"en":"The company introduced flexible hours to improve work-life balance.","zh-TW":"公司引入了彈性工作時間以改善工作生活平衡。"},{"en":"Flexible hours allow employees to avoid rush-hour commutes.","zh-TW":"彈性工作時間允許員工避開尖峰時間通勤。"}]', 'phrasal verb'),
('invoice processing', '', '', '[{"en":"The company automated invoice processing to reduce errors.","zh-TW":"公司自動化了發票處理以減少錯誤。"},{"en":"Efficient invoice processing ensures timely payments.","zh-TW":"高效的發票處理確保了及時付款。"}]', 'phrasal verb'),
('job vacancy', '', '', '[{"en":"The company posted ten job vacancies on its website.","zh-TW":"公司在其網站上發布了十個職位空缺。"},{"en":"Qualified candidates should apply for the job vacancy immediately.","zh-TW":"合格的候選人應立即申請職位空缺。"}]', 'phrasal verb'),
('meeting room', '', '', '[{"en":"Please book the meeting room in advance.","zh-TW":"請提前預訂會議室。"},{"en":"The meeting room is equipped with video conferencing tools.","zh-TW":"會議室配備了視訊會議工具。"}]', 'phrasal verb'),
('office supplies', '', '', '[{"en":"She ordered office supplies including paper, pens, and folders.","zh-TW":"她訂購了辦公用品，包括紙張、筆和資料夾。"},{"en":"Keep office supplies organized in clearly labeled storage.","zh-TW":"將辦公用品整齊地存放在有清晰標籤的地方。"}]', 'phrasal verb'),
('petty cash', '', '', '[{"en":"Small office expenses can be paid from the petty cash fund.","zh-TW":"小額辦公費用可從零用金支付。"},{"en":"All petty cash transactions must be recorded and receipted.","zh-TW":"所有零用金交易必須記錄並保留收據。"}]', 'phrasal verb'),
('banquet hall', '', '', '[{"en":"The banquet hall can accommodate up to 300 guests.","zh-TW":"宴會廳最多可容納300位賓客。"},{"en":"The annual gala will be held in the hotel''s banquet hall.","zh-TW":"年度晚會將在飯店的宴會廳舉行。"}]', 'phrasal verb'),
('catering manager', '', '', '[{"en":"The catering manager ensured the food was served on time.","zh-TW":"餐飲經理確保了食物準時上桌。"},{"en":"A skilled catering manager can handle events of any size.","zh-TW":"熟練的餐飲經理可以處理任何規模的活動。"}]', 'phrasal verb'),
('conference center', '', '', '[{"en":"The conference center has state-of-the-art audio-visual equipment.","zh-TW":"會議中心配備了最先進的視聽設備。"},{"en":"The annual summit will be held at the downtown conference center.","zh-TW":"年度峰會將在市中心的會議中心舉行。"}]', 'phrasal verb'),
('event coordinator', '', '', '[{"en":"The event coordinator handled all logistics for the conference.","zh-TW":"活動協調員處理了會議的所有後勤工作。"},{"en":"A good event coordinator anticipates problems before they arise.","zh-TW":"優秀的活動協調員在問題出現之前預先考慮到。"}]', 'phrasal verb'),
('guest speaker', '', '', '[{"en":"A renowned economist served as the guest speaker at the summit.","zh-TW":"一位知名經濟學家擔任峰會的特邀演講者。"},{"en":"The guest speaker shared insights from her 20 years of experience.","zh-TW":"特邀演講者分享了她20年經驗的見解。"}]', 'phrasal verb'),
('keynote address', '', '', '[{"en":"The prime minister delivered the opening keynote address.","zh-TW":"首相發表了開幕主題演說。"},{"en":"The keynote address set the tone for the two-day conference.","zh-TW":"主題演說為為期兩天的會議定下了基調。"}]', 'phrasal verb'),
('master of ceremonies', '', '', '[{"en":"The master of ceremonies welcomed the guests and introduced speakers.","zh-TW":"司儀歡迎了賓客並介紹了演講者。"},{"en":"She was chosen as master of ceremonies for the awards dinner.","zh-TW":"她被選為頒獎晚宴的司儀。"}]', 'phrasal verb'),
('panel discussion', '', '', '[{"en":"She participated in a panel discussion on renewable energy.","zh-TW":"她參加了一場關於可再生能源的小組討論。"},{"en":"The panel discussion provided diverse perspectives on the issue.","zh-TW":"小組討論提供了關於這個問題的多元觀點。"}]', 'phrasal verb'),
('registration desk', '', '', '[{"en":"Please check in at the registration desk upon arrival.","zh-TW":"抵達時請在報名處辦理登記。"},{"en":"The registration desk opens one hour before the event begins.","zh-TW":"報名處在活動開始前一小時開放。"}]', 'phrasal verb'),
('seminar room', '', '', '[{"en":"The seminar room holds up to 30 participants.","zh-TW":"研討室最多可容納30名參與者。"},{"en":"The training was conducted in the ground-floor seminar room.","zh-TW":"培訓在一樓的研討室進行。"}]', 'phrasal verb'),
('trade fair', '', '', '[{"en":"The company exhibited its new products at the international trade fair.","zh-TW":"公司在國際商展上展示了其新產品。"},{"en":"Trade fairs offer excellent networking opportunities.","zh-TW":"商展提供了絕佳的拓展人脈機會。"}]', 'phrasal verb'),
('venue booking', '', '', '[{"en":"Venue booking should be done at least three months in advance.","zh-TW":"場地預訂應至少提前三個月進行。"},{"en":"The venue booking confirmation was sent by email.","zh-TW":"場地預訂確認已透過電子郵件發送。"}]', 'phrasal verb'),
('balance forward', '', '', '[{"en":"The balance forward from last month was two thousand dollars.","zh-TW":"上個月的結轉餘額為兩千元。"},{"en":"Any unpaid balance will be carried forward to the next statement.","zh-TW":"任何未付餘額將結轉到下一期帳單。"}]', 'phrasal verb'),
('credit note', '', '', '[{"en":"The supplier issued a credit note for the returned goods.","zh-TW":"供應商為退貨發出了貸項通知單。"},{"en":"Apply the credit note to your next invoice.","zh-TW":"將貸項通知單應用於您的下一張發票。"}]', 'phrasal verb'),
('general ledger', '', '', '[{"en":"All transactions are posted to the general ledger.","zh-TW":"所有交易都記錄在總帳中。"},{"en":"The accountant reconciled the general ledger at month end.","zh-TW":"會計師在月底對總帳進行了核對。"}]', 'phrasal verb'),
('net loss', '', '', '[{"en":"The company reported a net loss of five million this quarter.","zh-TW":"公司本季度報告淨虧損五百萬。"},{"en":"A net loss may require cost-cutting measures to restore profitability.","zh-TW":"淨虧損可能需要降低成本措施來恢復盈利能力。"}]', 'phrasal verb'),
('petty cash voucher', '', '', '[{"en":"Fill in a petty cash voucher for every cash payment under twenty dollars.","zh-TW":"每次20元以下的現金付款都需填寫零用金憑單。"},{"en":"All petty cash vouchers must be approved by a supervisor.","zh-TW":"所有零用金憑單必須獲得主管批准。"}]', 'phrasal verb'),
('variable cost', '', '', '[{"en":"Raw materials are a major variable cost in manufacturing.","zh-TW":"原材料是製造業的主要變動成本。"},{"en":"As production increases, variable costs rise proportionally.","zh-TW":"隨著產量增加，變動成本按比例上升。"}]', 'phrasal verb'),
('bar chart', '', '', '[{"en":"The bar chart clearly shows the revenue growth over five years.","zh-TW":"長條圖清楚地顯示了五年來的收入增長。"},{"en":"Use a bar chart to compare sales across regions.","zh-TW":"使用長條圖比較各地區的銷售情況。"}]', 'phrasal verb'),
('bullet point', '', '', '[{"en":"Use bullet points to summarize key findings.","zh-TW":"使用項目符號來總結關鍵發現。"},{"en":"The presenter highlighted each bullet point on the slide.","zh-TW":"演講者強調了投影片上的每個要點。"}]', 'phrasal verb'),
('flip chart', '', '', '[{"en":"The trainer used a flip chart to outline the training plan.","zh-TW":"培訓師使用掛圖概述了培訓計劃。"},{"en":"Key points were written on the flip chart for everyone to see.","zh-TW":"關鍵要點被寫在掛圖上，供所有人看到。"}]', 'phrasal verb'),
('pie chart', '', '', '[{"en":"The pie chart illustrates the budget allocation clearly.","zh-TW":"圓餅圖清楚地說明了預算分配情況。"},{"en":"A pie chart is ideal for showing percentage breakdowns.","zh-TW":"圓餅圖非常適合顯示百分比分解。"}]', 'phrasal verb'),
('Q&A session', '', '', '[{"en":"The speaker opened the floor for a Q&A session.","zh-TW":"演講者開放了問答環節。"},{"en":"Please hold your questions until the Q&A session at the end.","zh-TW":"請將您的問題留到最後的問答環節。"}]', 'phrasal verb'),
('slide deck', '', '', '[{"en":"She prepared a compelling slide deck for the investor meeting.","zh-TW":"她為投資者會議準備了引人注目的簡報投影片組。"},{"en":"Keep your slide deck clear and not too text-heavy.","zh-TW":"保持您的簡報投影片清晰，不要過多文字。"}]', 'phrasal verb'),
('talking points', '', '', '[{"en":"He prepared talking points before the media interview.","zh-TW":"他在媒體採訪前準備了談話要點。"},{"en":"Share talking points with the team before client meetings.","zh-TW":"在客戶會議前與團隊分享發言重點。"}]', 'phrasal verb'),
('after-sales service', '', '', '[{"en":"The company is known for its excellent after-sales service.","zh-TW":"這家公司以其卓越的售後服務而聞名。"},{"en":"After-sales service includes warranty support and repairs.","zh-TW":"售後服務包括保固支援和維修。"}]', 'phrasal verb'),
('customer loyalty', '', '', '[{"en":"Customer loyalty programs reward repeat purchases.","zh-TW":"顧客忠誠度計劃獎勵重複購買。"},{"en":"Strong customer loyalty is built through trust and quality.","zh-TW":"強大的顧客忠誠度是透過信任和品質建立的。"}]', 'phrasal verb'),
('customer service representative', '', '', '[{"en":"The customer service representative resolved the issue immediately.","zh-TW":"客服代表立即解決了問題。"},{"en":"Friendly customer service representatives improve satisfaction scores.","zh-TW":"友善的客服代表提高了滿意度評分。"}]', 'phrasal verb'),
('exchange policy', '', '', '[{"en":"The store has a 30-day exchange policy.","zh-TW":"這家商店有30天的換貨政策。"},{"en":"Please read the exchange policy before making your purchase.","zh-TW":"購買前請閱讀換貨政策。"}]', 'phrasal verb'),
('floor manager', '', '', '[{"en":"Ask the floor manager for assistance with large purchases.","zh-TW":"請聯繫樓層管理員協助大宗採購。"},{"en":"The floor manager resolved the customer complaint quickly.","zh-TW":"樓層管理員迅速解決了顧客投訴。"}]', 'phrasal verb'),
('point of sale', '', '', '[{"en":"The new point of sale system speeds up checkout.","zh-TW":"新的銷售點系統加快了結帳速度。"},{"en":"Promotional materials placed at the point of sale boost impulse purchases.","zh-TW":"放置在銷售點的促銷材料促進了衝動購買。"}]', 'phrasal verb'),
('price tag', '', '', '[{"en":"Always check the price tag before adding items to your cart.","zh-TW":"將商品加入購物車前請務必查看價格標籤。"},{"en":"The price tag showed the item was on sale.","zh-TW":"價格標籤顯示該商品正在促銷。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('retail price', '', '', '[{"en":"The manufacturer suggested retail price is 99 dollars.","zh-TW":"製造商建議的零售價為99元。"},{"en":"Online retailers often undercut the recommended retail price.","zh-TW":"線上零售商通常低於建議零售價銷售。"}]', 'phrasal verb'),
('return policy', '', '', '[{"en":"The store offers a 30-day no-questions-asked return policy.","zh-TW":"商店提供30天無條件退貨政策。"},{"en":"Read the return policy before purchasing high-value items.","zh-TW":"購買高價商品前請閱讀退貨政策。"}]', 'phrasal verb'),
('sales representative', '', '', '[{"en":"The sales representative visited three clients this week.","zh-TW":"業務代表本週拜訪了三位客戶。"},{"en":"A skilled sales representative builds long-term client relationships.","zh-TW":"熟練的業務代表建立了長期的客戶關係。"}]', 'phrasal verb'),
('shelf life', '', '', '[{"en":"Always check the shelf life of perishable products.","zh-TW":"務必檢查易腐商品的保存期限。"},{"en":"Fresh produce has a shorter shelf life than canned goods.","zh-TW":"新鮮農產品的保存期限比罐頭食品短。"}]', 'phrasal verb'),
('shopping cart', '', '', '[{"en":"Add items to your shopping cart and proceed to checkout.","zh-TW":"將商品添加到購物車並繼續結帳。"},{"en":"She abandoned her shopping cart after seeing the shipping fee.","zh-TW":"她在看到運費後放棄了購物車。"}]', 'phrasal verb'),
('supplier evaluation', '', '', '[{"en":"Annual supplier evaluations help identify the best partners.","zh-TW":"年度供應商評估幫助識別最佳合作夥伴。"},{"en":"The procurement team uses a scorecard for supplier evaluation.","zh-TW":"採購團隊使用評分卡進行供應商評估。"}]', 'phrasal verb'),
('air freight', '', '', '[{"en":"Air freight is used for urgent or perishable shipments.","zh-TW":"空運用於緊急或易腐貨物的運輸。"},{"en":"The air freight cost was higher than anticipated.","zh-TW":"空運成本高於預期。"}]', 'phrasal verb'),
('bill of lading', '', '', '[{"en":"The shipper provided a bill of lading for the cargo.","zh-TW":"發貨人為貨物提供了提單。"},{"en":"A clean bill of lading indicates the goods arrived undamaged.","zh-TW":"清潔提單表明貨物完好無損地到達。"}]', 'phrasal verb'),
('cargo insurance', '', '', '[{"en":"Cargo insurance protects against loss during shipping.","zh-TW":"貨物保險保護貨物在運輸過程中免受損失。"},{"en":"Always obtain cargo insurance for high-value shipments.","zh-TW":"高價值貨物務必購買貨物保險。"}]', 'phrasal verb'),
('freight forwarder', '', '', '[{"en":"The freight forwarder handled all customs paperwork.","zh-TW":"貨運代理商處理了所有海關文件。"},{"en":"Partnering with a reliable freight forwarder simplifies logistics.","zh-TW":"與可靠的貨運代理商合作簡化了物流。"}]', 'phrasal verb'),
('port of origin', '', '', '[{"en":"The goods were shipped from their port of origin in Shanghai.","zh-TW":"貨物從上海的起運港發運。"},{"en":"The port of origin must be declared on the shipping documents.","zh-TW":"起運港必須在運輸文件上申報。"}]', 'phrasal verb'),
('sea freight', '', '', '[{"en":"Sea freight is more economical for large shipments.","zh-TW":"海運對大宗貨物更為經濟。"},{"en":"The sea freight arrived on schedule with no damage.","zh-TW":"海運貨物按時到達，無損壞。"}]', 'phrasal verb'),
('blood bank', '', '', '[{"en":"Donate blood to help replenish the blood bank.","zh-TW":"捐血以幫助補充血庫存量。"},{"en":"The blood bank maintained adequate supplies for emergencies.","zh-TW":"血庫維持了足夠的緊急備用存量。"}]', 'phrasal verb'),
('discharge summary', '', '', '[{"en":"The discharge summary outlined the treatment given and follow-up care.","zh-TW":"出院摘要概述了所接受的治療和後續護理。"},{"en":"Keep your discharge summary for future medical consultations.","zh-TW":"請保留出院摘要供未來的醫療諮詢使用。"}]', 'phrasal verb'),
('emergency surgery', '', '', '[{"en":"He underwent emergency surgery after the accident.","zh-TW":"他在事故後接受了緊急手術。"},{"en":"The hospital''s surgical team is available for emergency surgery 24 hours.","zh-TW":"醫院的外科團隊全天24小時提供緊急手術服務。"}]', 'phrasal verb'),
('family medicine', '', '', '[{"en":"Her family medicine doctor handles all routine health issues.","zh-TW":"她的家庭醫學醫生處理所有例行健康問題。"},{"en":"Family medicine emphasizes preventive care and long-term relationships.","zh-TW":"家庭醫學強調預防護理和長期醫患關係。"}]', 'phrasal verb'),
('first aid kit', '', '', '[{"en":"Every office should have a stocked first aid kit.","zh-TW":"每個辦公室都應備有裝滿用品的急救箱。"},{"en":"The first aid kit included bandages, antiseptic, and pain relievers.","zh-TW":"急救箱包含繃帶、消毒液和止痛藥。"}]', 'phrasal verb'),
('flu shot', '', '', '[{"en":"She gets a flu shot every autumn to stay healthy.","zh-TW":"她每年秋天接種流感疫苗以保持健康。"},{"en":"Flu shots are recommended for elderly and high-risk individuals.","zh-TW":"建議老年人和高風險人群接種流感疫苗。"}]', 'phrasal verb'),
('general practitioner', '', '', '[{"en":"See your general practitioner before consulting a specialist.","zh-TW":"在諮詢專科醫生之前先看全科醫生。"},{"en":"A general practitioner provides primary care for all age groups.","zh-TW":"全科醫生為所有年齡組提供基層醫療。"}]', 'phrasal verb'),
('medical insurance', '', '', '[{"en":"Medical insurance helps cover the cost of unexpected health issues.","zh-TW":"醫療保險有助於支付意外健康問題的費用。"},{"en":"The company provides comprehensive medical insurance for all employees.","zh-TW":"公司為所有員工提供全面的醫療保險。"}]', 'phrasal verb'),
('pharmacy benefit', '', '', '[{"en":"The pharmacy benefit plan covers most common prescriptions.","zh-TW":"藥品福利計劃涵蓋大多數常用處方藥。"},{"en":"Review your pharmacy benefit to understand medication coverage.","zh-TW":"查看您的藥品福利以了解藥物承保範圍。"}]', 'phrasal verb'),
('preventive care', '', '', '[{"en":"Regular screenings are an important part of preventive care.","zh-TW":"定期篩查是預防保健的重要組成部分。"},{"en":"Preventive care reduces long-term healthcare costs.","zh-TW":"預防保健降低了長期醫療費用。"}]', 'phrasal verb'),
('waiting room', '', '', '[{"en":"The waiting room was full of patients.","zh-TW":"候診室裡坐滿了患者。"},{"en":"Please wait in the waiting room until your name is called.","zh-TW":"請在候診室等候，直到叫到您的名字。"}]', 'phrasal verb'),
('bed and breakfast', '', '', '[{"en":"They chose a charming bed and breakfast in the countryside.","zh-TW":"他們選擇了鄉村的一家迷人的民宿。"},{"en":"A bed and breakfast is usually smaller and more personal than a hotel.","zh-TW":"民宿通常比飯店規模更小且更具個人特色。"}]', 'phrasal verb'),
('butler service', '', '', '[{"en":"The presidential suite comes with 24-hour butler service.","zh-TW":"總統套房提供24小時管家服務。"},{"en":"Butler service includes unpacking luggage and drawing baths.","zh-TW":"管家服務包括整理行李和放洗澡水。"}]', 'phrasal verb'),
('check-in procedure', '', '', '[{"en":"The hotel streamlined its check-in procedure to under three minutes.","zh-TW":"飯店將入住手續精簡到三分鐘以內。"},{"en":"Guests with pre-paid reservations enjoy a faster check-in procedure.","zh-TW":"預付訂金的賓客享有更快的入住手續。"}]', 'phrasal verb'),
('club floor', '', '', '[{"en":"Club floor guests have access to a private lounge and breakfast.","zh-TW":"行政樓層賓客可進入私人休息室和享用早餐。"},{"en":"Upgrading to the club floor includes exclusive evening cocktails.","zh-TW":"升級到行政樓層包含專屬的傍晚雞尾酒時光。"}]', 'phrasal verb'),
('connecting rooms', '', '', '[{"en":"We booked connecting rooms so the family could stay together.","zh-TW":"我們預訂了相通房間，方便全家住在一起。"},{"en":"Connecting rooms are ideal for families traveling with children.","zh-TW":"相通房間非常適合攜帶孩子旅行的家庭。"}]', 'phrasal verb'),
('double occupancy', '', '', '[{"en":"The hotel rate is based on double occupancy.","zh-TW":"飯店房價是基於雙人入住計算的。"},{"en":"Single travelers often pay extra when the rate assumes double occupancy.","zh-TW":"單人旅行者在房價假設雙人入住時通常需要支付額外費用。"}]', 'phrasal verb'),
('early check-in', '', '', '[{"en":"She requested early check-in due to an early morning flight.","zh-TW":"她因早班機而要求提前入住。"},{"en":"Early check-in is subject to availability and may incur a fee.","zh-TW":"提前入住視空房情況而定，可能需要支付費用。"}]', 'phrasal verb'),
('executive lounge', '', '', '[{"en":"Executive lounge guests enjoy complimentary snacks and drinks.","zh-TW":"行政貴賓室賓客享有免費零食和飲料。"},{"en":"The executive lounge offers a quiet workspace for business travelers.","zh-TW":"行政貴賓室為商務旅客提供安靜的工作空間。"}]', 'phrasal verb'),
('garden suite', '', '', '[{"en":"The garden suite has a private patio overlooking the grounds.","zh-TW":"花園套房設有可俯瞰庭院的私人露台。"},{"en":"They chose the garden suite for its peaceful outdoor setting.","zh-TW":"他們選擇了花園套房，因為其寧靜的戶外環境。"}]', 'phrasal verb'),
('group reservation', '', '', '[{"en":"The conference required a group reservation of 50 rooms.","zh-TW":"會議需要預訂50間房的團體訂房。"},{"en":"Group reservations typically qualify for special discounted rates.","zh-TW":"團體預訂通常可享有特別折扣價。"}]', 'phrasal verb'),
('hotel amenity', '', '', '[{"en":"The hotel amenities include a rooftop pool and fitness center.","zh-TW":"飯店設施包括頂樓泳池和健身中心。"},{"en":"Take full advantage of the hotel amenities during your stay.","zh-TW":"住宿期間請充分利用飯店設施。"}]', 'phrasal verb'),
('late arrival', '', '', '[{"en":"Please inform the hotel of a late arrival to secure the room.","zh-TW":"請通知飯店晚到情況，以確保房間不被取消。"},{"en":"A note was left for the late arrival guest at the front desk.","zh-TW":"前台為晚到的賓客留了一張便條。"}]', 'phrasal verb'),
('ocean view room', '', '', '[{"en":"She splurged on an ocean view room for their honeymoon.","zh-TW":"她為蜜月之旅訂了一間海景房。"},{"en":"Ocean view rooms are among the most popular choices at beach resorts.","zh-TW":"海景房是海灘度假村中最受歡迎的選擇之一。"}]', 'phrasal verb'),
('resort fee', '', '', '[{"en":"A daily resort fee covers access to the gym and pool.","zh-TW":"每日度假村服務費包含使用健身房和游泳池的費用。"},{"en":"The resort fee was not disclosed at the time of booking.","zh-TW":"度假村服務費在預訂時未予披露。"}]', 'phrasal verb'),
('single occupancy', '', '', '[{"en":"The single occupancy rate includes all standard amenities.","zh-TW":"單人入住費率包含所有標準設施。"},{"en":"Solo travelers may pay a single occupancy supplement.","zh-TW":"單人旅行者可能需要支付單人入住附加費。"}]', 'phrasal verb'),
('turndown service', '', '', '[{"en":"Turndown service includes chocolates on the pillow.","zh-TW":"夜床服務包括在枕頭上放巧克力。"},{"en":"Premium rooms receive a complimentary turndown service each evening.","zh-TW":"高級客房每晚享有免費夜床服務。"}]', 'phrasal verb'),
('twin bed', '', '', '[{"en":"They requested a twin bed room to share as friends.","zh-TW":"他們作為朋友要求了雙床房間。"},{"en":"A twin bed configuration is ideal for business travelers sharing a room.","zh-TW":"雙床配置對於共享房間的商務旅客來說非常理想。"}]', 'phrasal verb'),
('carbon capture', '', '', '[{"en":"Carbon capture technology removes CO2 from the atmosphere.","zh-TW":"碳捕獲技術從大氣中去除二氧化碳。"},{"en":"The factory installed a carbon capture system to reduce emissions.","zh-TW":"工廠安裝了碳捕獲系統以減少排放量。"}]', 'phrasal verb'),
('clean water', '', '', '[{"en":"Access to clean water is a basic human right.","zh-TW":"獲得清潔飲水是基本人權。"},{"en":"The NGO works to provide clean water to rural communities.","zh-TW":"非政府組織致力於為農村社區提供清潔飲水。"}]', 'phrasal verb'),
('ecological footprint', '', '', '[{"en":"Reducing your ecological footprint helps preserve natural resources.","zh-TW":"減少您的生態足跡有助於保護自然資源。"},{"en":"The company monitors its ecological footprint annually.","zh-TW":"公司每年監測其生態足跡。"}]', 'phrasal verb'),
('emission reduction', '', '', '[{"en":"The government set ambitious emission reduction targets.","zh-TW":"政府設定了雄心勃勃的減排目標。"},{"en":"Emission reduction requires changes in energy use and transport.","zh-TW":"減排需要改變能源使用和交通方式。"}]', 'phrasal verb'),
('environmental awareness', '', '', '[{"en":"The school launched a campaign to raise environmental awareness.","zh-TW":"學校發起了一場提升環保意識的活動。"},{"en":"Environmental awareness drives consumer demand for green products.","zh-TW":"環保意識推動消費者對綠色產品的需求。"}]', 'phrasal verb'),
('green certification', '', '', '[{"en":"The building achieved LEED green certification.","zh-TW":"這棟大樓獲得了LEED綠色認證。"},{"en":"Green certification demonstrates a company''s commitment to sustainability.","zh-TW":"綠色認證展示了公司對永續發展的承諾。"}]', 'phrasal verb'),
('natural disaster', '', '', '[{"en":"The earthquake was one of the worst natural disasters in decades.","zh-TW":"這次地震是幾十年來最嚴重的天然災害之一。"},{"en":"International aid arrived quickly after the natural disaster.","zh-TW":"自然災難後，國際援助迅速到達。"}]', 'phrasal verb'),
('net zero emissions', '', '', '[{"en":"The company committed to net zero emissions by 2040.","zh-TW":"公司承諾到2040年實現淨零排放。"},{"en":"Net zero emissions require both reducing and offsetting carbon.","zh-TW":"淨零排放需要同時減少和抵消碳排放。"}]', 'phrasal verb'),
('rainwater harvesting', '', '', '[{"en":"The building uses a rainwater harvesting system for irrigation.","zh-TW":"該建築使用雨水收集系統進行灌溉。"},{"en":"Rainwater harvesting reduces dependence on municipal water supplies.","zh-TW":"雨水收集減少了對市政供水的依賴。"}]', 'phrasal verb'),
('renewable resource', '', '', '[{"en":"Wind and solar power are examples of renewable resources.","zh-TW":"風能和太陽能是可再生資源的例子。"},{"en":"Transitioning to renewable resources is essential for sustainability.","zh-TW":"過渡到可再生資源對永續發展至關重要。"}]', 'phrasal verb');